module Top;
  bit clk, en;
  int n, m;
  initial forever begin @(posedge clk iff en); n++; end
  initial forever begin @(clk iff en); m++; end
  initial begin
    #1 clk = 1;
    #1 clk = 0;
    #1 en = 1;
    #1 clk = 1;
    #1 en = 0;
    #1 en = 1;
    #1 clk = 0;
    #1 clk = 1;
    #1 $display("n=%0d m=%0d", n, m);
    $finish;
  end
endmodule
